/* Helper (no dependencies): D.byId(id) -> the row or null. A school or campus without a row is "Belum diketahui". */
(function (D) {
  'use strict';
  if (!D || !D.rows) return;
  var by = null;
  D.byId = function (id) {
    if (!by) { by = {}; D.rows.forEach(function (r) { by[r.id] = r; }); }
    return Object.prototype.hasOwnProperty.call(by, String(id)) ? by[String(id)] : null;
  };
})(typeof window !== 'undefined' ? window.MCD_INSTITUTION_TIERS : undefined);
